import type { Href } from 'expo-router';

/**
 * Routes used by the Home cards, Care Connect and the sync result.
 * Expo's typed routes (.expo/types/router.d.ts) are regenerated by
 * `npx expo start`; widening through `string` keeps these type-safe even
 * before that file knows about newly added screens.
 */
const r = (path: string) => path as Href;

export const ROUTES = {
  yourGoGirl: r('/your-go-girl'),
  care: r('/care'),
  syncResult: r('/sync-result'),
  healthCheck: r('/health-check'),
};
